package com.androidharness.fixture.phoneuse;

import android.app.Activity;
import android.app.Instrumentation;
import android.app.KeyguardManager;
import android.app.UiAutomation;
import android.accessibilityservice.AccessibilityServiceInfo;
import android.graphics.Rect;
import android.os.Bundle;
import android.os.ParcelFileDescriptor;
import android.os.SystemClock;
import android.view.accessibility.AccessibilityNodeInfo;
import android.view.accessibility.AccessibilityWindowInfo;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.function.Predicate;

/** On the explicitly opened page, read just the release/debug Harness consent panel's response.
 * Never follows nodes into other apps, enters text, approves a task, or executes a DirectAction. */
public class ReadPageProbe extends Instrumentation {
    String target, harness;
    private boolean startFixture;
    private boolean captureFixture;
    private boolean verifyCancel;
    UiAutomation ui;

    @Override public void onCreate(Bundle args) {
        super.onCreate(args);
        target = args.getString("target", "");
        harness = args.getString("harness", "com.androidharness.app");
        startFixture = "true".equals(args.getString("startFixture"));
        captureFixture = startFixture && "true".equals(args.getString("captureFixture"));
        verifyCancel = startFixture && "true".equals(args.getString("verifyCancel"));
        start();
    }
    @Override public void onStart() {
        Bundle answer = new Bundle();
        boolean panelOpened = false;
        int result = Activity.RESULT_CANCELED;
        try {
            if (!target.matches("[a-z][a-z0-9_.]+") || !harness.matches("com\\.androidharness\\.app(\\.debug)?"))
                throw new IllegalArgumentException("Invalid package");
            if (getContext().getSystemService(KeyguardManager.class).isDeviceLocked())
                throw new IllegalStateException("Phone is locked");
            ui = getUiAutomation(UiAutomation.FLAG_DONT_SUPPRESS_ACCESSIBILITY_SERVICES);
            if (verifyCancel) {
                AccessibilityServiceInfo info = ui.getServiceInfo();
                info.flags |= AccessibilityServiceInfo.FLAG_RETRIEVE_INTERACTIVE_WINDOWS;
                ui.setServiceInfo(info);
            }
            if (startFixture) {
                if (!"com.androidharness.fixture.phoneuse".equals(target)) throw new IllegalStateException("Wrong fixture package");
                command("am start -W -n com.androidharness.fixture.phoneuse/.DirectActionFixtureActivity");
                SystemClock.sleep(300);
            }
            command("input keyevent KEYCODE_ASSIST");
            AccessibilityNodeInfo open = waitPanelEntry(6000);
            if (open == null) {
                // Some vendor policies do not map a synthetic ASSIST key to the elected service.
                command("cmd voiceinteraction show");
                open = waitPanelEntry(5500);
            }
            if (open == null) throw new IllegalStateException("No Harness assistant panel");
            panelOpened = true;
            int initialWindow = open.getWindowId();
            openTaskReview(open);
            AccessibilityNodeInfo consent = waitNode(n -> label(n,target), 4500);
            if (consent == null)
                throw new IllegalStateException("Consent did not identify the requested package");
            boolean sameWindow = consent.getWindowId() == initialWindow;
            answer.putString("window_ids", initialWindow + " -> " + consent.getWindowId());
            if (verifyCancel && !sameWindow) throw new IllegalStateException("Confirmation opened a different accessibility window");
            click(waitNode(n -> label(n,"查看本页动作","Check page actions"), 4000));
            AccessibilityNodeInfo found = waitNode(n -> {
                String id = n.getViewIdResourceName();
                if (!isResult(n.getText())) return false;
                return id == null || id.endsWith("phone_page_result");
            }, 10000);
            if (found == null) throw new IllegalStateException("No discovery result");
            // The status is generated by Harness. Never collect screen text from the target app.
            String status = found.getText().toString().split("\\n")[0];
            answer.putString("discovery", status);
            if (status.matches(".*[0-9].*")) {
                java.util.ArrayList<String> ids = new java.util.ArrayList<>();
                find(ui.getRootInActiveWindow(), n -> {
                    String id = n.getViewIdResourceName();
                    if (id != null && id.endsWith("phone_page_action_id") && n.getText() != null && ids.size() < 32)
                        ids.add(n.getText().toString());
                    return false;
                });
                if (!ids.isEmpty()) answer.putString("action_ids", android.text.TextUtils.join(", ",ids));
            }
            if (target.equals("com.androidharness.fixture.phoneuse") && status.matches(".*[0-9].*")) {
                boolean visible = waitNode(n -> n.getText() != null && n.getText().toString().contains("show_test_receipt"), 1500) != null;
                answer.putBoolean("fixture_action_visible", visible);
                if (visible && captureFixture) {
                    android.graphics.Bitmap frame = ui.takeScreenshot();
                    if (frame != null) try (java.io.FileOutputStream out = new java.io.FileOutputStream(
                        new java.io.File(getTargetContext().getExternalFilesDir(null),"page-discovery.png"))) {
                        frame.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);
                    } finally { frame.recycle(); }
                }
            }
            if (verifyCancel) {
                AccessibilityNodeInfo input = waitNode(AccessibilityNodeInfo::isEditable, 3500);
                if (input == null || input.getWindowId() != initialWindow) throw new IllegalStateException("No inline editor");
                Rect bounds = new Rect();
                input.getBoundsInScreen(bounds);
                command("input tap " + bounds.centerX() + " " + bounds.centerY());
                Bundle text = new Bundle();
                text.putCharSequence(AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE, "Fixture draft");
                if (!input.performAction(AccessibilityNodeInfo.ACTION_SET_TEXT, text))
                    throw new IllegalStateException("Cannot enter disposable fixture text");
                Rect ime = new Rect();
                long end = SystemClock.elapsedRealtime() + 3500;
                do {
                    for (AccessibilityWindowInfo window : ui.getWindows())
                        if (window.getType() == AccessibilityWindowInfo.TYPE_INPUT_METHOD) window.getBoundsInScreen(ime);
                    if (ime.height() > 0) break;
                    SystemClock.sleep(100);
                } while (SystemClock.elapsedRealtime() < end);
                AccessibilityNodeInfo allow = waitNode(n -> label(n,"允许并开始","Allow and start"), 2500);
                if (allow == null || ime.height() <= 0) throw new IllegalStateException("No visible keyboard or start button");
                allow.getBoundsInScreen(bounds);
                if (bounds.isEmpty() || Rect.intersects(ime,bounds)) throw new IllegalStateException("Keyboard covers the start button");
                answer.putBoolean("inline_start_visible_above_ime",true);
                click(waitNode(n -> label(n,"取消","Cancel"),3000));
                AccessibilityNodeInfo normal = waitPanelEntry(5000);
                if (normal == null || normal.getWindowId() != initialWindow)
                    throw new IllegalStateException("Cancel did not return to the ordinary assistant input");
                answer.putBoolean("cancel_restored_chat",true);
            }
            result = Activity.RESULT_OK;
        } catch (Exception e) {
            answer.putString("failure", e.toString());
            if (ui != null) {
                AccessibilityNodeInfo root = ui.getRootInActiveWindow();
                answer.putString("window_package",root == null ? "(none)" : String.valueOf(root.getPackageName()));
            }
        } finally {
            if (panelOpened && ui != null) {
                // Back only while Harness itself is the active window; never dismiss another app.
                try {
                    for (int i = 0; i < 2 && ownsRoot(); i++) {
                        command("input keyevent KEYCODE_BACK"); SystemClock.sleep(300);
                    }
                } catch (Exception ignored) {}
            }
            finish(result, answer);
        }
    }
    AccessibilityNodeInfo waitPanelEntry(long timeout) {
        return waitNode(n -> label(n,"操作手机","Operate phone","新问题","New question"),timeout);
    }
    void openTaskReview(AccessibilityNodeInfo entry) {
        if (entry == null) throw new IllegalStateException("No Harness assistant panel");
        if (label(entry,"操作手机","Operate phone")) { click(entry); return; }
        // In a resumed conversation the ordinary composer is the entry. The exact local phone
        // instruction only opens the review; don't clear history, call a model or operate the target.
        AccessibilityNodeInfo keyboard = waitNode(n -> label(n,"改用键盘","Type instead"),250);
        if (keyboard != null) click(keyboard);
        AccessibilityNodeInfo field = waitNode(AccessibilityNodeInfo::isEditable,3000);
        if (field == null || (field.getText() != null && field.getText().length() != 0))
            throw new IllegalStateException("No empty assistant composer; leaving its draft unchanged");
        Bundle args = new Bundle();
        args.putCharSequence(AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE,"操作手机：查看本页动作");
        if (!field.performAction(AccessibilityNodeInfo.ACTION_SET_TEXT,args)) throw new IllegalStateException("Cannot enter local review request");
        click(waitNode(n -> label(n,"发送","Send"),2000));
    }
    private boolean isResult(CharSequence value) {
        if (value == null) return false;
        String s = value.toString();
        return s.startsWith("本页") || s.startsWith("页面已变更") || s.startsWith("Android 未能") ||
            s.startsWith("This page offers ") || s.startsWith("Available page actions:") || s.startsWith("The page did not") ||
            s.startsWith("The page changed") || s.startsWith("Android could not query");
    }
    void command(String command) throws Exception {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(new ParcelFileDescriptor.AutoCloseInputStream(ui.executeShellCommand(command))))) {
            while (reader.readLine() != null) { /* Drain; no app data is requested. */ }
        }
    }
    boolean ownsRoot() {
        if (android.os.Build.VERSION.SDK_INT >= 33) ui.clearCache();
        AccessibilityNodeInfo root = ui.getRootInActiveWindow();
        return root != null && harness.contentEquals(root.getPackageName());
    }
    AccessibilityNodeInfo waitNode(Predicate<AccessibilityNodeInfo> p, long millis) {
        long until = SystemClock.elapsedRealtime() + millis;
        do {
            if (android.os.Build.VERSION.SDK_INT >= 33) ui.clearCache();
            AccessibilityNodeInfo node = find(ui.getRootInActiveWindow(), p);
            if (node != null) return node;
            SystemClock.sleep(110);
        } while (SystemClock.elapsedRealtime() < until);
        return null;
    }
    private AccessibilityNodeInfo find(AccessibilityNodeInfo node, Predicate<AccessibilityNodeInfo> p) {
        if (node == null || !harness.contentEquals(node.getPackageName())) return null;
        if (node.isVisibleToUser() && p.test(node)) return node;
        for (int i = 0; i < node.getChildCount(); i++) {
            AccessibilityNodeInfo found = find(node.getChild(i), p);
            if (found != null) return found;
        }
        return null;
    }
    static boolean label(AccessibilityNodeInfo node, String... labels) {
        for (String s : labels) if (s.contentEquals(node.getText() == null ? "" : node.getText()) ||
            s.contentEquals(node.getContentDescription() == null ? "" : node.getContentDescription())) return true;
        return false;
    }
    static void click(AccessibilityNodeInfo node) {
        while (node != null && !node.isClickable()) node = node.getParent();
        if (node == null || !node.isEnabled() || !node.performAction(AccessibilityNodeInfo.ACTION_CLICK))
            throw new IllegalStateException("Harness probe control unavailable");
    }
}
